"use client";

import React from "react";

import PricingCard from "@/registry/open-source/price-card";

export default function Usage() {
	return (
		<div className="h-screen w-full flex items-center justify-center relative overflow-hidden bg-black">
			<PricingCard />
		</div>
	);
}

"use client";

import { Check } from "lucide-react";
import { motion } from "motion/react";

import { ScalingButton } from "./scaling-button";

export default function PricingCard() {
	const features = [
		"2 Senior Developers",
		"Landing Page Development",
		"15-20 Days Service (One time)",
		"Private Discord Channel",
		"One Request at a time",
	];

	return (
		<div className="flex items-center justify-center">
			<motion.div
				className="w-full max-w-md rounded-3xl bg-gradient-to-b from-gray-800 to-gray-900 p-6 text-white shadow-xl"
				initial={{ opacity: 0, y: 50 }}
				animate={{ opacity: 1, y: 0 }}
				transition={{ duration: 0.5 }}
			>
				<h2 className="mb-2 text-2xl font-bold">Extend MVP</h2>
				<div className="mb-4 flex items-baseline">
					<span className="text-5xl font-extrabold">$3000</span>
					<span className="ml-2 text-xl">/month</span>
				</div>
				<p className="mb-6 text-gray-400">Product Development</p>
				<ul className="mb-6 space-y-3">
					{features.map((feature, index) => (
						<motion.li
							key={index + "price-card"}
							className="flex items-center space-x-3"
							initial={{ opacity: 0, x: -50 }}
							animate={{ opacity: 1, x: 0 }}
							transition={{ duration: 0.5, delay: index * 0.1 }}
						>
							<motion.span
								className="flex h-5 w-5 flex-shrink-0 items-center justify-center rounded-full bg-priceAccent"
								initial={{ scale: 0 }}
								animate={{ scale: 1 }}
								transition={{
									type: "spring",
									stiffness: 500,
									delay: index * 0.1 + 0.2,
								}}
							>
								<Check className="h-3 w-3 text-white" />
							</motion.span>
							<span>{feature}</span>
						</motion.li>
					))}
				</ul>
				<ScalingButton className="w-full bg-white text-black hover:bg-white/90">
					Order Now
				</ScalingButton>
			</motion.div>
		</div>
	);
}

import * as React from "react";

import { Button } from "@/components/ui/button";
import { motion } from "motion/react";

type ScalingButtonProps = {
	springTransition?: {
		type: string;
		stiffness: number;
		damping: number;
	};
};

const springTransitionDefault = {
	type: "spring",
	stiffness: 400,
	damping: 12,
};

export const ScalingButton = React.forwardRef<
	HTMLButtonElement,
	ScalingButtonProps
>(({ children, springTransition = springTransitionDefault, ...props }, ref) => {
	return (
		<motion.div
			whileHover={{ scale: 1.1 }}
			whileTap={{ scale: 0.9 }}
			transition={springTransition}
		>
			<Button ref={ref} {...props}>
				{children}
			</Button>
		</motion.div>
	);
});

ScalingButton.displayName = "ScalingButton";

import * as React from "react";

import { cn } from "@/registry/utils/utils";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };

import registry from "@/registry.json";
import { clsx, type ClassValue } from "clsx";
import type { RegistryItem } from "shadcn/registry";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

const components = registry.items as unknown as RegistryItem[];

export const getComponents = (selectedTags: any[] = []): RegistryItem[] => {
	return selectedTags.length
		? components.filter((component) =>
				selectedTags.every(
					(tag) => component.meta?.tags?.includes(tag) ?? false
				)
			)
		: components;
};

export const getComponentsByNames = (names: string[]): RegistryItem[] => {
	const componentsMap = new Map(components.map((comp) => [comp.name, comp]));

	return names
		.map((name) => componentsMap.get(name))
		.filter((comp): comp is RegistryItem => comp !== undefined);
};

export const getAvailableTags = (selectedTags: any[]): any[] => {
	if (!selectedTags.length) return [];

	// Get all components that have all the selected tags
	const matchingComponents = components.filter((component) =>
		selectedTags.every((tag) => component.meta?.tags?.includes(tag) ?? false)
	);

	// Get all unique tags from the matching components
	const availableTags = new Set<any>();
	matchingComponents.forEach((component) => {
		component.meta?.tags?.forEach((tag: any) => {
			if (!selectedTags.includes(tag)) {
				availableTags.add(tag);
			}
		});
	});

	return Array.from(availableTags);
};

export const convertRegistryPaths = (content: string): string => {
	return content
		.replace(/@\/registry\/default\/ui/g, "@/components/ui")
		.replace(/@\/registry\/default\/compositions/g, "@/components")
		.replace(/@\/registry\/default\/hooks/g, "@/hooks")
		.replace(/@\/registry\/default\/lib/g, "@/lib");
};
